#!/usr/bin/env node
/*
 * Generates C data tables for the firmware from the simulator's single source
 * of truth (fonts, formula library, unit factors). Run: npm run gen
 * Generated files are committed; CI checks they are up to date (--check).
 */
'use strict';
const fs = require('fs');
const path = require('path');
const Font = require('../simulator/js/core/font.js');
const Formulas = require('../simulator/js/core/formulas.js');
const Units = require('../simulator/js/core/units.js');

const ROOT = path.join(__dirname, '..');
const HDR = '/* AUTO-GENERATED by tools/gen_firmware_tables.js - DO NOT EDIT. */\n';
const cstr = (s) => '"' + String(s).replace(/\\/g, '\\\\').replace(/"/g, '\\"').replace(/\n/g, '\\n') + '"';
const hex = (b) => '0x' + b.toString(16).padStart(2, '0').toUpperCase();
const num = (v) => { const s = String(v); return /[.eE]/.test(s) || !Number.isInteger(v) ? s : s + '.0'; };

function font() {
  let o = HDR + '#include "mt_font.h"\n\n';
  o += 'const uint8_t mt_font5x7_ascii[95][5] = {\n';
  Font.ASCII.forEach((g, i) => { o += `    {${g.map(hex).join(', ')}}, /* ${JSON.stringify(String.fromCharCode(0x20 + i))} */\n`; });
  o += '};\n\n';
  o += 'const mt_glyph_extra_t mt_font5x7_extra[] = {\n';
  for (const ch of Font.EXTRA_ORDER) o += `    {0x${ch.codePointAt(0).toString(16).toUpperCase()}u, {${Font.EXTRA[ch].map(hex).join(', ')}}}, /* ${ch} */\n`;
  o += '};\n';
  o += `const size_t mt_font5x7_extra_count = ${Font.EXTRA_ORDER.length};\n\n`;
  o += 'const mt_glyph_tiny_t mt_font3x5[] = {\n';
  for (const ch of Object.keys(Font.TINY_SRC)) o += `    {'${ch === '\\' ? '\\\\' : ch === "'" ? "\\'" : ch}', {${Font.tinyGlyph(ch).map(hex).join(', ')}}},\n`;
  o += '};\n';
  o += `const size_t mt_font3x5_count = ${Object.keys(Font.TINY_SRC).length};\n`;
  return o;
}

function formulas() {
  let o = HDR + '#include "formulas.h"\n\n';
  o += 'const formula_category_t formula_categories[] = {\n';
  Formulas.CATEGORIES.forEach(([id, name]) => { o += `    {${cstr(id)}, ${cstr(name)}},\n`; });
  o += '};\n';
  o += `const size_t formula_category_count = ${Formulas.CATEGORIES.length};\n\n`;
  Formulas.LIST.forEach((f, i) => {
    o += `static const formula_var_t vars_${i}[] = {\n`;
    f.vars.forEach(([s, d, u]) => { o += `    {${cstr(s)}, ${cstr(d)}, ${cstr(u)}, ${num(f.example.in[s])}},\n`; });
    o += '};\n';
  });
  o += '\nconst formula_t formula_list[] = {\n';
  Formulas.LIST.forEach((f, i) => {
    o += `    {${cstr(f.id)}, ${cstr(f.cat)}, ${cstr(f.name)}, ${cstr(f.formula)}, ${cstr(f.out)}, ${cstr(f.expr)}, ${cstr(f.units)}, ` +
      `${f.angle === 'deg' ? 'true' : 'false'}, vars_${i}, ${f.vars.length}, ${num(f.example.out)}},\n`;
  });
  o += '};\n';
  o += `const size_t formula_count = ${Formulas.LIST.length};\n`;
  return o;
}

function conversions() {
  let o = HDR + '#include "conversions.h"\n\n';
  Units.CATEGORIES.forEach((c, i) => {
    o += `static const conv_unit_t units_${i}[] = {\n`;
    c.units.forEach(([s, n, f]) => { o += `    {${cstr(s)}, ${cstr(n)}, ${f == null ? '0.0' : num(f)}},\n`; });
    o += '};\n';
  });
  o += '\nconst conv_category_t conv_categories[] = {\n';
  Units.CATEGORIES.forEach((c, i) => { o += `    {${cstr(c.id)}, ${cstr(c.name)}, ${cstr(c.base)}, ${c.affine ? 'true' : 'false'}, units_${i}, ${c.units.length}},\n`; });
  o += '};\n';
  o += `const size_t conv_category_count = ${Units.CATEGORIES.length};\n`;
  return o;
}

const outputs = {
  'firmware/components/display/src/font_data.c': font(),
  'firmware/components/formulas/src/formulas_data.c': formulas(),
  'firmware/components/conversions/src/conversions_data.c': conversions(),
};

const check = process.argv.includes('--check');
let stale = 0;
for (const [rel, content] of Object.entries(outputs)) {
  const file = path.join(ROOT, rel);
  if (check) {
    const cur = fs.existsSync(file) ? fs.readFileSync(file, 'utf8') : '';
    if (cur !== content) { console.error('desatualizado: ' + rel); stale++; }
  } else {
    fs.mkdirSync(path.dirname(file), { recursive: true });
    fs.writeFileSync(file, content);
    console.log('gerado: ' + rel);
  }
}
process.exit(stale ? 1 : 0);
